fn solve(input: Vec<char>) -> Vec<char> {
    // We only care about the first two characters, which are guaranteed to be '0'..='9'.
    let a = input[0];
    let b = input[1];

    // Map each digit to its "good count"
    let cnt = |c: char| -> usize {
        match c {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => 0, // unreachable under the problem assumptions
        }
    };

    let product = cnt(a) * cnt(b);
    // Convert the product to its decimal representation and collect into a Vec<char>
    let mut output: Vec<char> = product.to_string().chars().collect();
    // Append the required trailing newline
    output.push('\n');
    output
}